INSERT INTO zc_private.zsl_tournament_level_state(id_round,timeslot,playlist_index,id_level,deadline) SELECT $1,$3,$4,$5,to_timestamp($6::double precision) FROM zc_private.zsl_tournament_state WHERE id_round=$1 AND owner=$2 AND lease_until>clock_timestamp() ON CONFLICT(id_round,timeslot,playlist_index) DO UPDATE SET deadline=zsl_tournament_level_state.deadline WHERE zsl_tournament_level_state.id_level IS NOT DISTINCT FROM excluded.id_level
